item.command:
/bin/bash -lc "python - <<'PY'
import requests, time, json
s=requests.Session(); s.headers.update({'Accept':'application/json','User-Agent':'codex-analysis'})
rsids=['rs1150779','rs4308051','rs2871960','rs224333','rs2011603','rs3791679','rs9435734']
seen=set()
for rsid in rsids:
    print('\\n###',rsid)
    data=s.get(f'https://www.ebi.ac.uk/gwas/rest/api/singleNucleotidePolymorphisms/{rsid}/associations', timeout=30).json()
    for a in data.get('_embedded',{}).get('associations',[])[:30]:
        href=a.get('_links',{}).get('association',{}).get('href') or a.get('_links',{}).get('self',{}).get('href')
        ahref=href
        # traits
        traits=[]
        eth=[]
        for lname in ['efoTraits','backgroundEfoTraits']:
            h=a.get('_links',{}).get(lname,{}).get('href')
            if h:
                try:
                    j=s.get(h,timeout=20).json()
                    for tr in j.get('_embedded',{}).get('efoTraits',[]):
                        traits.append(tr.get('trait'))
                except Exception as e: traits.append('ERR:'+str(e))
        sh=a.get('_links',{}).get('study',{}).get('href')
        study={}
        if sh:
